// Global context or flow context
let mode = flow.get('mode') || 'on_off'; // on_off, p, pi
let target = flow.get('target') || 50.0;
let kp = flow.get('kp') || 0.05;
let ki = flow.get('ki') || 0.01;
let integral = flow.get('integral') || 0.0;

let level = msg.payload.water_sensor_depth;
let error = target - level;
let valve = 0.0;

if (mode === 'on_off') {
    // Lab 2: Hysteresis +-10%
    let upper = target * 1.10;
    let lower = target * 0.90;
    let last_valve = flow.get('valve') || 0;
    if (level <= lower) {
        valve = 100.0;
    } else if (level >= upper) {
        valve = 0.0;
    } else {
        valve = last_valve;
    }
} else if (mode === 'p') {
    // Lab 3: P Control
    valve = kp * error * 100.0;
    valve = Math.max(0.0, Math.min(100.0, valve));
} else if (mode === 'pi') {
    // Lab 4: PI Control
    integral += error * 0.5;
    integral = Math.max(-50.0, Math.min(50.0, integral));
    flow.set('integral', integral);
    valve = (kp * error + ki * integral) * 100.0;
    valve = Math.max(0.0, Math.min(100.0, valve));
}

flow.set('valve', valve);
msg.payload = valve;
return msg;
